import React, { useState, useEffect, useRef } from "react";
import { Link } from "react-router-dom";
import { motion, useInView, useAnimation } from "framer-motion";
import {
  ArrowRight, Shield, Truck, Award, RefreshCw, Star,
  Leaf, Package, Zap, Gift, CheckCircle, Phone, ChevronLeft, ChevronRight,
} from "lucide-react";
import ProductCard from "../components/ProductCard";
import BulkCalculator from "../components/BulkCalculator";
import Hero3D from "../components/Hero3D";
import { DEMO_PRODUCTS, formatPrice } from "../utils/helpers";

/* ── Framer helpers ─────────────────────────────────────────── */
function FadeUp({ children, delay = 0, className = "" }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: "-60px" });
  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, y: 40 }}
      animate={inView ? { opacity: 1, y: 0 } : {}}
      transition={{ duration: 0.7, delay, ease: [0.22, 1, 0.36, 1] }}
      className={className}
    >
      {children}
    </motion.div>
  );
}

function ScaleIn({ children, delay = 0, className = "" }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: "-60px" });
  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, scale: 0.85 }}
      animate={inView ? { opacity: 1, scale: 1 } : {}}
      transition={{ duration: 0.6, delay, ease: [0.22, 1, 0.36, 1] }}
      className={className}
    >
      {children}
    </motion.div>
  );
}

/* ── Static data ────────────────────────────────────────────── */
const FEATURES = [
  { icon: <Shield size={26} />, title: "100% Authentic", desc: "Directly sourced from farms. No additives." },
  { icon: <Truck size={26} />, title: "Free Delivery", desc: "Pan-India shipping. Free above ₹499." },
  { icon: <Award size={26} />, title: "FSSAI Certified", desc: "Stringent quality checks on every batch." },
  { icon: <RefreshCw size={26} />, title: "7-Day Returns", desc: "Hassle-free return policy, no questions." },
];

const CATEGORIES = [
  { name: "Almonds", img: "https://images.unsplash.com/photo-1508061253366-f7da158b6d46?w=300&q=80" },
  { name: "Cashews", img: "https://images.unsplash.com/photo-1573555657105-47a0bb37c3ea?w=300&q=80" },
  { name: "Pistachios", img: "https://images.unsplash.com/photo-1502825751399-28baa9b81efe?w=300&q=80" },
  { name: "Walnuts", img: "https://images.unsplash.com/photo-1524593656068-fbac72624bb0?w=300&q=80" },
  { name: "Dates", img: "https://images.unsplash.com/photo-1604329760661-e71dc83f8f26?w=300&q=80" },
  { name: "Gift Hampers", img: "https://images.unsplash.com/photo-1549465220-1a8b9238cd48?w=300&q=80" },
];

const TESTIMONIALS = [
  { name: "Priya Sharma", city: "Mumbai", rating: 5, text: "Best quality almonds I've ever bought! Freshness is unmatched. Will definitely order again.", product: "Premium Almonds" },
